select m.id, 'story', 'Ma famille', '{"text": "Je m''appelle Léa et j''habite à Lyon avec ma famille. Mon père est professeur et ma mère est médecin. J''ai un frère, Hugo, et une sœur, Chloé. Le dimanche, nous déjeunons chez mes grands-parents. Ma grand-mère prépare un gâteau délicieux. J''adore ma famille !", "translation": "My name is Léa and I live in Lyon with my family. My father is a teacher and my mother is a doctor. I have a brother, Hugo, and a sister, Chloé. On Sundays, we have lunch at my grandparents'' house. My grandmother makes a delicious cake. I love my family!", "translations": {"es": "Me llamo Léa y vivo en Lyon con mi familia. Mi padre es profesor y mi madre es médica. Tengo un hermano, Hugo, y una hermana, Chloé. Los domingos almorzamos en casa de mis abuelos. Mi abuela prepara un pastel delicioso. ¡Adoro a mi familia!"}, "highlighted_words": ["famille", "père", "mère", "frère", "sœur", "grands-parents"]}'::jsonb, (select coalesce(max(order_index), 0) from lessons where module_id = m.id) + 1, true
from modules m where m.language_code = 'fr' and m.slug = 'familyhome'
  and not exists (select 1 from lessons l where l.module_id = m.id and l.type = 'story');
