select m.id, 'story', 'Une journée normale', '{"text": "Je me lève à sept heures. À huit heures, je prends le bus pour aller au travail. Je déjeune à midi avec mes collègues. Le soir, je rentre à six heures. Aujourd''hui, c''est lundi, et j''ai trois réunions ! Demain, c''est mardi.", "translation": "I get up at seven o''clock. At eight o''clock, I take the bus to go to work. I have lunch at noon with my colleagues. In the evening, I come home at six o''clock. Today is Monday, and I have three meetings! Tomorrow is Tuesday.", "translations": {"es": "Me levanto a las siete. A las ocho tomo el autobús para ir al trabajo. Almuerzo a mediodía con mis compañeros. Por la tarde vuelvo a casa a las seis. Hoy es lunes, ¡y tengo tres reuniones! Mañana es martes."}, "highlighted_words": ["sept", "huit", "midi", "six", "trois", "lundi"]}'::jsonb, (select coalesce(max(order_index), 0) from lessons where module_id = m.id) + 1, true
from modules m where m.language_code = 'fr' and m.slug = 'numberstime'
  and not exists (select 1 from lessons l where l.module_id = m.id and l.type = 'story');
